def compute(vars):
    securities = vars["v1"]
    exercise_price = vars["v2"]
    total_value_dollars = securities * exercise_price
    value_in_millions = total_value_dollars / 1_000_000

    return {
        "value": value_in_millions,
        "trace": {
            "securities": securities,
            "exercise_price_usd_per_security": exercise_price,
            "total_value_dollars": total_value_dollars,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "dollars"
            }
        }
    }
